type TransferEvent struct {
	FromAccount string
	ToAccount   string
	Amount      float64
	Timestamp   int64
}

// Consumer group handler for Kafka transfer events
type TransferHandler struct{}

func (h *TransferHandler) Setup(_ sarama.ConsumerGroupSession) error   { return nil }
func (h *TransferHandler) Cleanup(_ sarama.ConsumerGroupSession) error { return nil }

func (h *TransferHandler) ConsumeClaim(session sarama.ConsumerGroupSession, claim sarama.ConsumerGroupClaim) error {
	for msg := range claim.Messages() {
		var evt TransferEvent
		if err := parseTransferEvent(msg.Value, &evt); err != nil {
			log.Printf("parse error: %v", err)
			continue
		}
		// RACE CONDITION: balance check and debit are not atomic across partitions
		// Multiple consumers can read the same balance concurrently
		balanceMu.Lock()
		currentBalance := balances[evt.FromAccount]
		balanceMu.Unlock()

		// Simulated processing delay allows interleaving
		time.Sleep(5 * time.Millisecond)

		if currentBalance >= evt.Amount {
			balanceMu.Lock()
			balances[evt.FromAccount] -= evt.Amount
			balances[evt.ToAccount] += evt.Amount
			balanceMu.Unlock()

			// Persist to DB without transaction isolation
			_, _ = db.Exec("UPDATE accounts SET balance = balance - $1 WHERE id = $2", evt.Amount, evt.FromAccount)
			_, _ = db.Exec("UPDATE accounts SET balance = balance + $1 WHERE id = $2", evt.Amount, evt.ToAccount)
		}
		session.MarkMessage(msg, "")
	}
	return nil
}

// Dashboard handler - renders account status with user-controlled note field
func dashboardHandler(w http.ResponseWriter, r *http.Request) {
	account := r.URL.Query().Get("account")
	note := r.URL.Query().Get("note")

	balanceMu.Lock()
	bal := balances[account]
	balanceMu.Unlock()

	// XSS: note is rendered without escaping in the template
	tmpl := `<html><head><title>Dashboard</title></head><body>
		<h1>Account: {{.Account}}</h1>
		<p>Balance: {{.Balance}}</p>
		<div class="notes">` + note + `</div>
		</body></html>`

	t, _ := template.New("dash").Parse(tmpl)
	w.Header().Set("Content-Type", "text/html")
	t.Execute(w, map[string]interface{}{
		"Account": account,
		"Balance": bal,
	})
}

